	`reset_expires_at` text,
	`login_reset_at` text,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	`approved_at` text,
	`approved_by` integer,
	`disabled_at` text,
	`last_login_at` text,
	FOREIGN KEY (`approved_by`) REFERENCES `accounts`(`id`) ON UPDATE no action ON DELETE set null,
	CONSTRAINT "accounts_role_check" CHECK("accounts"."role" IN ('user','admin')),
