-- Full text search over todos, notes, comments and people of every account. Trigram tokens find any part
-- of a word (3 characters or more) and remove_diacritics folds umlauts ("muller" finds "Müller"). Every
-- query filters account_id. No triggers: the services keep the index up to date in the same transaction
-- as each change and rebuild it at every start. Never exported.
CREATE VIRTUAL TABLE `search_fts` USING fts5(
  account_id UNINDEXED,
  kind UNINDEXED,
  ref_id UNINDEXED,
  todo_id UNINDEXED,
  title,
  body,
  tokenize = 'trigram remove_diacritics 1'
);
